import unittest


class TestKeyValueStore(unittest.TestCase):
    def setUp(self):
        self.store = KeyValueStore()

    def test_ac_1_add_b_with_value_2(self):
        self.store.set('b', 2)
        self.assertEqual(self.store.get('b'), 2)

    def test_ac_2_add_a_with_value_1(self):
        self.store.set('a', 1)
        self.assertEqual(self.store.get('a'), 1)

    def test_ac_3_keys_return_sorted_list(self):
        self.store.set('b', 2)
        self.store.set('a', 1)
        self.assertListEqual(self.store.keys(), ['a', 'b'])

    def test_ac_4_get_returns_none_after_deleting_a(self):
        self.store.set('a', 1)
        self.store.delete('a')
        self.assertIsNone(self.store.get('a'))", "path": "tests/test_spec_ac.py"}, "tool": "append_file"}

